import base64,hashlib,json,os,subprocess,time
from pathlib import Path
B=Path('/dataset/shaoshitong/recursive-bran-a-h100-20261012/recovery-from100-20261013')
f=B/'final51713-worker-recovery-v1';f.mkdir(exist_ok=True)
assert not (f/'launch.json').exists()
payload={'entry.py': '', 'final_worker.py': '', 'final_eval.py': ''}
manifest={}
for name,data in payload.items():
 raw=base64.b64decode(data);dst=f/name;assert not dst.exists();dst.write_bytes(raw);assert dst.read_bytes()==raw;manifest[name]=hashlib.sha256(raw).hexdigest()
with (f/'controller.log').open('ab') as log:
 child=subprocess.Popen(['python3','-B','-u',str(f/'entry.py')],env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1'),stdout=log,stderr=log,start_new_session=True)
time.sleep(2)
record=dict(time=time.time(),pid=child.pid,source_manifest=manifest,source=str(f/'entry.py'),alive=child.poll() is None)
(f/'launch.json').write_text(json.dumps(record,indent=2));print(json.dumps(record));assert child.poll() is None,(f/'controller.log').read_text()
